class Spacecraft {
  constructor(name, initialX, initialY) {
    this.name = name;
    this.currentX = initialX;
    this.currentY = initialY;
  }

  travelToCoordinates(targetX, targetY) {
    this.currentX = targetX;
    this.currentY = targetY;
    return `${this.name} is now at (${this.currentX}, ${this.currentY}).`;
  }

  // TODO: This method handles a separate concern (communication).
  // Extract it into a new class to follow the Single Responsibility Principle.
  // The Spacecraft class should then *use* an instance of this new communication class.
  transmitMessage(message) {
    const timestamp = new Date().toISOString();
    return `[${timestamp}] ${this.name} transmitted: "${message}"`;
  }
}

// Example Usage (will need to be updated after refactor)
const enterprise = new Spacecraft("Enterprise", 0, 0);
console.log(enterprise.travelToCoordinates(100, 50));
console.log(enterprise.transmitMessage("Hello Command, this is Enterprise!"));

