class CommunicationModule {
  constructor(craftName) {
    this.craftName = craftName;
  }

  transmitMessage(message) {
    const timestamp = new Date().toISOString();
    return `[${timestamp}] ${this.craftName} transmitted: "${message}"`;
  }
}

class Spacecraft {
  constructor(name, initialX, initialY) {
    this.name = name;
    this.currentX = initialX;
    this.currentY = initialY;
    // Spacecraft now contains a CommunicationModule
    this.communicationModule = new CommunicationModule(this.name);
  }

  travelToCoordinates(targetX, targetY) {
    this.currentX = targetX;
    this.currentY = targetY;
    return `${this.name} is now at (${this.currentX}, ${this.currentY}).`;
  }

  // Spacecraft delegates communication responsibility to its module
  sendMessage(message) {
    return this.communicationModule.transmitMessage(message);
  }
}

// Example Usage
const enterprise = new Spacecraft("Enterprise", 0, 0);
console.log(enterprise.travelToCoordinates(100, 50));
console.log(enterprise.sendMessage("Hello Command, this is Enterprise!"));

